#nullable enable // autogenerated

using System;
using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Entities;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine;
using PVZEngine.Callbacks;
using PVZEngine.Entities;
using PVZEngine.Level;
using UnityEngine;

namespace MVZ2.Vanilla.Projectiles
{
    public static class VanillaProjectileExt
    {
        public static Entity? ShootProjectile(this Entity entity)
        {
            var shootParams = entity.GetShootParams();
            return entity.ShootProjectile(shootParams);
        }
        public static Entity? ShootProjectile(this Entity entity, NamespaceID? projectileID)
        {
            var shootParams = entity.GetShootParams();
            shootParams.projectileID = projectileID;
            return entity.ShootProjectile(shootParams);
        }
        public static Entity? ShootProjectile(this Entity entity, NamespaceID? projectileID, Vector3 velocity)
        {
            var shootParams = entity.GetShootParams();
            shootParams.projectileID = projectileID;
            shootParams.velocity = velocity;
            return entity.ShootProjectile(shootParams);
        }
        public static Entity? ShootProjectile(this Entity entity, ShootParams parameters)
        {
            if (parameters.soundID != null)
                entity.PlaySound(parameters.soundID);
            var projectileID = parameters.projectileID;
            if (projectileID == null)
                return null;
            var projectileDefinition = entity.Level.Content.GetEntityDefinition(projectileID);
            if (projectileDefinition == null)
                return null;

            var velocity = entity.ModifyProjectileVelocity(parameters.velocity);
            var position = parameters.position;
            var projectileSize = projectileDefinition.GetSize();
            var projectileBoundsPivot = projectileDefinition.GetBoundsPivot();
            position += Vector3.Scale(projectileBoundsPivot - parameters.pivot, projectileSize);

            var param = parameters.spawnParam;
            param.SetProperty(VanillaEntityProps.DAMAGE, parameters.damage);
            param.SetProperty(EngineEntityProps.FACTION, parameters.faction);
            param.EntityVelocity = velocity;
            return entity.Spawn(projectileDefinition, position, param)?.Let(e =>
            {
                entity.Level.Triggers.RunCallbackFiltered(VanillaLevelCallbacks.POST_PROJECTILE_SHOT, new EntityCallbackParams(e), e.GetDefinitionID());
            });

        }
        public static ShootParams GetShootParams(this Entity entity)
        {
            var velocity = entity.GetShotVelocity();
            velocity.x *= entity.GetFacingX();
            return new ShootParams()
            {
                projectileID = entity.GetProjectileID(),
                position = entity.GetShootPoint(),
                pivot = entity.GetShotPivot(),
                faction = entity.GetFaction(),
                damage = entity.GetDamage(),
                soundID = entity.GetShootSound(),
                velocity = velocity,
                spawnParam = entity.GetSpawnParams(),
            };
        }
        public static Vector3 ModifyShotOffset(this Entity entity, Vector3 offset)
        {
            offset.x *= entity.GetFacingX();
            return offset;
        }
        public static Vector3 GetShootPoint(this Entity entity)
        {
            Vector3 offset = entity.GetShotOffset();
            offset = entity.ModifyShotOffset(offset);
            return entity.Position + offset;
        }
        public static Vector3 GetLobVelocity(Vector3 source, Vector3 target, float maxY, float gravity, bool passesMaxY = true)
        {
            //问题：已知y = a[(x - h)]^2 + k经过原点，求h。

            //其中，x为点的x值，y为点的y值，a为偏曲率，h为抛物线对称轴，k为最大高度。
            //因为抛物线经过原点，故得：
            //0 = a(-h) ^ 2 + k
            //0 = ah ^ 2 + k
            //a = -k / h ^ 2

            //将a = -k / h ^ 2 代入y = a[(x - h)]^2 + k，得：
            //y = (-k/h^2) * (x-h)^2 + k
            //y = (-k/h^2) * (x^2 - 2xh + h^2) + k
            //y = -k * (x^2 - 2xh + h^2) / h^2 + k
            //y = (-kx^2 + 2kxh - kh^2) / h^2 + k
            //y = -kx^2/h^2 + 2kx/h - k + k
            //y = -kx^2/h^2 + 2kx/h
            //y = (-kx^2 + 2kxh)/
            //yh^2 = -kx^2 + 2kxh
            //yh^2 - 2kxh + kx^2 = 0

            //通过二次函数求根公式x = (-b±√(b^2 - 4ac))/ (2a)可得：
            //h = (2kx±√(4k^2x^2 - 4kx^2y))/ 2y
            //h = (kx±√(x^2 * (k^2 - k*y)))/ y

            //当y = 0时，h = x / 2
            //其中，如果点(x, y)在靠近Y轴一侧，则
            //h = (kx+√(x^2 * (k^2 - k*y)))/ y
            //如果点在(x, y)在远离Y轴一侧，则
            //h = (kx-√(x^2 * (k^2 - k*y)))/ y

            //当k > 0时，函数向下开口，y≤k
            //当k < 0时，函数向上开口，y≥k
            //当k = 0时，h不存在
            //当x = 0时，函数在x = 0上有无数个值

            var relativePosition = target - source;
            var k = maxY - source.y;
            if (k > 0)
            {
                if (relativePosition.y > k)
                    throw new ArgumentException("If maxY is positive, it must be greater than target.y.");
                if (gravity < 0)
                    throw new ArgumentException("If maxY is positive, the gravity must be positive.");
            }
            else if (k < 0)
            {
                if (relativePosition.y > k)
                    throw new ArgumentException("If maxY is negative, it must be less than target.y.");
                if (gravity < 0)
                    throw new ArgumentException("If maxY is negative, the gravity must be negative.");
            }
            else
            {
                throw new InvalidOperationException("MaxY cannot be equal to source.y.");
            }

            var horiVector = new Vector2(relativePosition.x, relativePosition.z);
            var horiDirection = horiVector.normalized;
            var length = horiVector.magnitude;
            // 到达最高点t帧过后的y速度y1 = -gt
            // 到达最高点t帧过后的y位置 = k + y1 * (1 + t) / 2
            // 按照目标的最终y位置求出到达最高点后的时间。
            var sign = passesMaxY ? -1 : 1;
            var a = -gravity / 2;
            var b = 0;
            var c = k - relativePosition.y;
            var fallTime = (-b + sign * Mathf.Sqrt(b * b - 4 * a * c)) / (2 * a);
            if (Mathf.Approximately(length, 0))
            {
                // 两点位置一致
                return new Vector3(0, fallTime * gravity, 0);
            }

            // 两点位置不同
            float highestLength;
            if (Mathf.Approximately(relativePosition.y, 0))
            {
                highestLength = length * 0.5f;
            }
            else
            {
                var sqrMaxY = Mathf.Pow(k, 2);
                var sqrLength = Mathf.Pow(length, 2);
                var factor = Mathf.Sqrt(sqrLength * (sqrMaxY - k * relativePosition.y));
                highestLength = (k * length + sign * factor) / relativePosition.y;
            }
            // 根据后半段时间求出总时间。
            var fallPercent = (length - highestLength) / length;
            var totalTime = fallTime / fallPercent;
            var ascendTime = totalTime - fallTime;

            // 根据总时间获取水平移速。
            var velHori = length / totalTime;

            // 到达最高点的y位置 k = y1 + g * (1 + t) / 2
            // 所以 y1 = k - g * (1 + t) / 2
            // 获取垂直移速y1。
            var velVert = gravity * ascendTime;

            var hori = horiDirection * velHori;
            return new Vector3(hori.x, velVert, hori.y);
        }
        public static Vector3 GetLobVelocityByTime(Vector3 source, Vector3 target, float maxTime, float gravity)
        {
            float x, y, z;
            x = (target.x - source.x) / maxTime;
            y = (target.y - source.y) / maxTime + gravity * maxTime * 0.5f;
            z = (target.z - source.z) / maxTime;
            return new Vector3(x, y, z);
        }

        #region 出屏幕
        public static bool IsProjectileOutsideView(this Entity proj)
        {
            var bounds = proj.GetBounds();
            var position = proj.Position;
            return bounds.max.x < LevelPositions.PROJECTILE_LEFT_BORDER ||
                bounds.min.x > LevelPositions.PROJECTILE_RIGHT_BORDER ||
                position.z > LevelPositions.PROJECTILE_UP_BORDER ||
                position.z < LevelPositions.PROJECTILE_DOWN_BORDER ||
                position.y > LevelPositions.PROJECTILE_TOP_BORDER ||
                position.y < LevelPositions.PROJECTILE_BOTTOM_BORDER;
        }
        #endregion
    }
    public struct ShootParams
    {
        public NamespaceID? projectileID;
        public Vector3 position;
        public Vector3 pivot;
        public Vector3 velocity;
        public NamespaceID? soundID;
        public float damage;
        public int faction;
        public SpawnParams spawnParam;
    }
}
